class PersistentSeg:
    def __init__(self, n):
        self.L = [0]; self.R = [0]; self.S = [0]; self.n = n
    def build(self, l, r):
        self.L.append(0); self.R.append(0); self.S.append(0)
        node = len(self.S)-1
        if l == r: return node
        m = (l+r)//2
        self.L[node] = self.build(l, m)
        self.R[node] = self.build(m+1, r)
        return node
    def update(self, prev, l, r, pos):
        self.L.append(self.L[prev]); self.R.append(self.R[prev]); self.S.append(self.S[prev]+1)
        node = len(self.S)-1
        if l == r: return node
        m = (l+r)//2
        if pos <= m: self.L[node] = self.update(self.L[prev], l, m, pos)
        else: self.R[node] = self.update(self.R[prev], m+1, r, pos)
        return node
    def kth(self, u, v, l, r, k):
        if l == r: return l
        m = (l+r)//2
        cnt = self.S[self.L[v]] - self.S[self.L[u]]
        if k <= cnt: return self.kth(self.L[u], self.L[v], l, m, k)
        return self.kth(self.R[u], self.R[v], m+1, r, k-cnt)
